import{_ as o}from"./chunks/master-icon.QdaGkTY4.js";import{_ as r,C as s,o as d,c as l,a5 as e,E as n}from"./chunks/framework.DuVjalqf.js";const i="/rb_cobot_docs_muscat/images/move-menu/master-where.avif",m="/rb_cobot_docs_muscat/images/move-menu/master-panel.avif",P=JSON.parse('{"title":"Master Mode","description":"","frontmatter":{"title":"Master Mode"},"headers":[],"relativePath":"manual/move-menu/master.md","filePath":"manual/move-menu/master.md","lastUpdated":1792396350000}'),c={name:"manual/move-menu/master.md"};function h(p,t,M,u,_,g){const a=s("DemoFrame");return d(),l("div",null,[t[0]||(t[0]=e('<h1 id="master-mode" tabindex="-1">Master Mode <a class="header-anchor" href="#master-mode" aria-label="Permalink to &quot;Master Mode&quot;">​</a></h1><p><img src="'+o+'" alt="Master Mode 아이콘"> 한 로봇의 움직임을 다른 로봇이 따라 하게 하는 <strong>Master Mode</strong>를 설정하는 메뉴입니다.</p><p>화면에서 파란 테두리로 표시한 곳입니다. 오른쪽 메뉴의 항목을 누르면 옆에 이 패널이 열립니다.</p><p><img src="'+i+'" alt="Master Mode 위치"></p><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2>',5)),n(a,{id:"move-menu-master"}),t[1]||(t[1]=e('<h2 id="패널-화면" tabindex="-1">패널 화면 <a class="header-anchor" href="#패널-화면" aria-label="Permalink to &quot;패널 화면&quot;">​</a></h2><p><img src="'+m+'" alt="Master Mode 패널"></p><p>위 화면은 가상 로봇(데모)에서 캡처한 것이라 값은 실제 로봇과 다를 수 있습니다. 데모의 가상 로봇은 한 대뿐이라 따라가는 로봇이 없으므로, 실습에서는 화면 구성만 볼 수 있습니다.</p><h2 id="master-mode란" tabindex="-1">Master Mode란 <a class="header-anchor" href="#master-mode란" aria-label="Permalink to &quot;Master Mode란&quot;">​</a></h2><p><strong>Master Mode</strong>는 두 로봇(양팔)이 함께 구성된 시스템에서, 한 로봇의 움직임을 다른 로봇이 <strong>그대로 따라 하게 하는</strong> 기능입니다.</p><ul><li><strong>마스터</strong>: 이 메뉴에서 모드를 켠 로봇입니다. 사람이 조그 등으로 직접 움직이는 쪽입니다.</li><li><strong>따라가는 로봇</strong>: 마스터와 함께 구성된 다른 로봇입니다. 마스터가 움직이는 동안 매 순간 목표를 받아 따라 움직입니다.</li></ul><p>따라가는 방식에 따라 두 가지 모드가 있습니다.</p><table tabindex="0"><thead><tr><th>버튼</th><th>프로그램 명령에서의 이름</th><th>따라가는 기준</th></tr></thead><tbody><tr><td><strong>Master Move J</strong></td><td>반영된 조인트 각도</td><td>마스터의 <strong>관절 각도</strong></td></tr><tr><td><strong>Master Move L</strong></td><td>동기화된 직교 좌표</td><td>마스터의 <strong>TCP 위치·방향</strong></td></tr><tr><td><strong>Master Mode Stop</strong></td><td>끄기</td><td>따라 하기를 끝냅니다.</td></tr></tbody></table><h2 id="j-모드와-l-모드의-차이" tabindex="-1">J 모드와 L 모드의 차이 <a class="header-anchor" href="#j-모드와-l-모드의-차이" aria-label="Permalink to &quot;J 모드와 L 모드의 차이&quot;">​</a></h2><h3 id="master-move-j-—-관절-각도를-따라가기" tabindex="-1">Master Move J — 관절 각도를 따라가기 <a class="header-anchor" href="#master-move-j-—-관절-각도를-따라가기" aria-label="Permalink to &quot;Master Move J — 관절 각도를 따라가기&quot;">​</a></h3><p>마스터의 현재 J0~J6 관절 각도를 따라가는 로봇의 목표 관절 각도로 보냅니다. 이때 각도를 그대로 보내지 않고, <strong>J1·J2·J4·J6은 부호를 반대로</strong> 보냅니다(J0·J3·J5는 그대로). 따라가는 로봇은 이 목표 각도를 향해 관절 이동을 합니다.</p><ul><li>두 로봇이 같은 관절 구성으로 서로 짝이 되어 움직이도록 맞추는 방식입니다.</li><li>두 로봇의 TCP 위치 관계를 따로 유지하지는 않습니다. 관절 각도만 맞춥니다.</li></ul><h3 id="master-move-l-—-tcp-위치·방향-관계를-유지하며-따라가기" tabindex="-1">Master Move L — TCP 위치·방향 관계를 유지하며 따라가기 <a class="header-anchor" href="#master-move-l-—-tcp-위치·방향-관계를-유지하며-따라가기" aria-label="Permalink to &quot;Master Move L — TCP 위치·방향 관계를 유지하며 따라가기&quot;">​</a></h3><p>모드를 켜는 순간 <strong>마스터 TCP와 따라가는 로봇 TCP 사이의 상대 위치·방향</strong>을 기억합니다. 이후 마스터의 TCP가 움직이면, 그 상대 관계가 유지되도록 따라가는 로봇의 목표 TCP 위치·방향을 계산해 직선 이동으로 따라갑니다.</p><ul><li>켠 시점의 두 TCP 배치가 그대로 유지되며 함께 움직입니다.</li><li>팔꿈치 자세(AA)는 켠 시점의 값을 유지합니다.</li></ul><h3 id="한눈에-비교" tabindex="-1">한눈에 비교 <a class="header-anchor" href="#한눈에-비교" aria-label="Permalink to &quot;한눈에 비교&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Master Move J</th><th>Master Move L</th></tr></thead><tbody><tr><td>마스터에서 읽는 값</td><td>관절 각도</td><td>TCP 위치·방향</td></tr><tr><td>따라가는 로봇의 움직임</td><td>목표 관절 각도로 관절 이동</td><td>목표 TCP 위치·방향으로 직선 이동</td></tr><tr><td>유지되는 것</td><td>관절 각도의 대응(일부 관절은 부호 반대)</td><td>켠 시점의 두 TCP 상대 위치·방향</td></tr><tr><td>기준이 정해지는 시점</td><td>항상 마스터의 현재 관절 각도</td><td>모드를 켠 시점의 두 로봇 배치</td></tr></tbody></table><h2 id="사용-방법" tabindex="-1">사용 방법 <a class="header-anchor" href="#사용-방법" aria-label="Permalink to &quot;사용 방법&quot;">​</a></h2><ol><li>두 로봇이 모두 정지해 있는 상태에서 <strong>Master Move J</strong> 또는 <strong>Master Move L</strong>을 누릅니다. 로봇이 움직이는 중이면 켜지지 않습니다.</li><li>마스터 로봇을 조그 등으로 움직입니다. 따라가는 로봇이 함께 움직입니다.</li><li>끝낼 때는 <strong>Master Mode Stop</strong>을 누릅니다.</li></ol><p>Master Mode가 켜져 있는 동안에는 &quot;Master Mode Activated&quot; 알림이 표시되고, 알림의 <strong>Finish Master Mode</strong> 버튼으로도 끌 수 있습니다.</p><div class="tip custom-block"><p class="custom-block-title">자동으로 꺼지는 경우</p><p>모드를 켠 뒤 어느 한 로봇의 서보·기준 상태가 켤 때와 달라지면 Master Mode는 자동으로 꺼집니다.</p></div><div class="tip custom-block"><p class="custom-block-title">프로그램에서 쓰기</p><p>프로그램에도 같은 모드를 고르는 <strong>마스터 모드 선택</strong> 명령이 있습니다. 선택지는 끄기, 반영된 조인트 각도(J), 동기화된 직교 좌표(L)입니다.</p></div><p>로봇이 연결되지 않은 상태(<code>DISCONNECT</code>)에서는 세 버튼이 모두 비활성화됩니다.</p><div class="warning custom-block"><p class="custom-block-title">실제 로봇을 조작할 때</p><p>마스터를 움직이면 따라가는 로봇도 함께 움직입니다. 두 로봇 주변에 사람과 장애물이 없는지 확인하고, 긴급 정지 버튼을 바로 누를 수 있는 상태에서 조작하세요.</p></div>',24))])}const T=r(c,[["render",h]]);export{P as __pageData,T as default};
